/**
 * API entry point, generated by `cef-init` (commoneventframework) and kept as in the CEF README.
 *
 * - `handler` is the AWS Lambda handler: CEF turns the incoming event into a CommonEvent, finds
 *   the route declared in root.yaml, runs its input parser, then its handler.
 * - With `--local` (npm run dev), CEF starts a dev HTTP server on port 8888 that calls `handler`.
 *
 * The application logic is not here: routes point to src/handlers (HTTP layer), which dispatch
 * commands to src/modules (business logic).
 */
import { loadEnv } from "commoneventframework";

// Starts loading .env as early as possible; every request awaits it before running.
const envReady = loadEnv();

// Registers every x-handler / x-inputParser referenced in root.yaml (generated by `npm run codegen`).
import "./generated/HandlerRegistry";

import {
  APIGatewayProxyStructuredResultV2,
  Context,
  buildCommonEvent,
  getRouteConfig,
  resolveHandlerRef,
  Response,
  setLambdaContext,
  startDevServer,
} from "commoneventframework";
import { CommonEvent, LambdaEvent } from "commoneventframework/dist/types/commonEvent";
import { HandlerFn, InputParserFn } from "./handlers/types";

export const handler = async (
  event: LambdaEvent,
  context: Context
): Promise<APIGatewayProxyStructuredResultV2> => {
  await envReady;
  await setLambdaContext(context);
  // Normalizes the incoming event (API Gateway, dev server, ...) into one CommonEvent shape.
  const commonEvent: CommonEvent = await buildCommonEvent(event);

  try {
    // Finds the root.yaml route matching the method and path.
    const routeConfig = getRouteConfig(commonEvent);

    if (!routeConfig || !routeConfig.handler) {
      return new Response(404, { error: "Route not found" });
    }

    const handlerFn = resolveHandlerRef(routeConfig.handler) as HandlerFn | undefined;
    const parserFn = routeConfig.inputParser
      ? (resolveHandlerRef(routeConfig.inputParser) as InputParserFn | undefined)
      : undefined;

    if (!handlerFn) {
      return new Response(500, { error: `Handler "${routeConfig.handler}" not found` });
    }

    // The input parser runs synchronously (no await). If it returns a Response
    // (e.g. 400 / 401 / 403), that response is sent and the handler is skipped.
    const input = parserFn ? parserFn(commonEvent) : {};
    if (input instanceof Response) return input;

    const result = await handlerFn(input, commonEvent);

    // A handler may return a full Response (custom status) or a plain object (200).
    if (result && "statusCode" in result) {
      return result as APIGatewayProxyStructuredResultV2;
    }
    return new Response(200, result as object);
  } catch (err) {
    console.error("handler error", err);
    return new Response(500, err as object);
  }
};

// Local development server (npm run dev).
if (process.argv.includes("--local")) {
  startDevServer(handler);
}
